CREATE TABLE card_cache (id TEXT PRIMARY KEY, name TEXT NOT NULL, supertype TEXT, subtypes TEXT, types TEXT, rarity TEXT, set_id TEXT, set_name TEXT, number TEXT, image_url TEXT, price_trend REAL, price_normal REAL, price_holofoil REAL, price_currency TEXT DEFAULT 'USD', price_source TEXT, cmc REAL, color_identity TEXT, language TEXT DEFAULT 'English', printed_name TEXT, tcgplayer_product_id INTEGER, last_updated DATETIME DEFAULT CURRENT_TIMESTAMP, tcgplayer_url TEXT, cardmarket_url TEXT, price_etched REAL, oracle_id TEXT, scryfall_search_eligible INTEGER, oracle_text TEXT, oracle_faces TEXT, price_estimated INTEGER NOT NULL DEFAULT 0);
CREATE TABLE collection (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, card_id TEXT NOT NULL, quantity INTEGER DEFAULT 1, condition TEXT, printing TEXT, language TEXT, purchase_price REAL, added_at DATETIME, is_trade INTEGER DEFAULT 0, notes TEXT, is_proxy INTEGER DEFAULT 0);
CREATE TABLE oracle_tag_generations (id INTEGER PRIMARY KEY, active INTEGER NOT NULL DEFAULT 0);
CREATE TABLE oracle_tag_aliases (generation_id INTEGER, alias TEXT, tag_id TEXT);
CREATE TABLE oracle_tag_closure (generation_id INTEGER, ancestor_tag_id TEXT, descendant_tag_id TEXT);
CREATE TABLE oracle_tag_assignments (generation_id INTEGER, tag_id TEXT, oracle_id TEXT);
